//! Encoders compared byte-for-byte with output of PHP 8.3's ext/gd linked
//! against the same system libgd (fixtures generated by `tests/fixtures`'
//! script, see the module docs of each test), and decoders checked on
//! those files.

use php_gd::{errors, Decoder, Encoder, Font, Image};

const FIXTURES: &str = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures");

fn fixture(name: &str) -> Vec<u8> {
    std::fs::read(format!("{FIXTURES}/{name}")).expect("fixture")
}

/// The drawing of the generator's `tc()`:
///
/// ```php
/// $im = imagecreatetruecolor(32, 24);
/// $red = imagecolorallocate($im, 255, 0, 0);
/// $blue = imagecolorallocatealpha($im, 0, 0, 255, 64);
/// imagefilledrectangle($im, 2, 2, 20, 12, $red);
/// imageline($im, 0, 23, 31, 0, $blue);
/// imageellipse($im, 16, 12, 20, 10, 0x00ff00);
/// imagestring($im, 2, 1, 10, "Hi", 0xffffff);
/// ```
fn truecolor() -> Image {
    let im = Image::new_truecolor(32, 24).expect("image");
    let red = im.color_allocate(255, 0, 0);
    let blue = im.color_allocate_alpha(0, 0, 255, 64);
    im.filled_rectangle(2, 2, 20, 12, red);
    im.line(0, 23, 31, 0, blue);
    im.ellipse(16, 12, 20, 10, 0x00ff00);
    let f = Font::builtin(2);
    for (i, b) in b"Hi".iter().enumerate() {
        let x = 1 + i32::try_from(i).unwrap_or(0) * f.width();
        im.draw_char(&f, x, 10, i32::from(*b), 0x00ff_ffff);
    }
    im
}

/// The generator's `pal()`:
///
/// ```php
/// $im = imagecreate(16, 16);
/// $white = imagecolorallocate($im, 255, 255, 255);
/// $black = imagecolorallocate($im, 0, 0, 0);
/// $green = imagecolorallocate($im, 0, 200, 0);
/// imagefilledrectangle($im, 3, 3, 12, 12, $green);
/// imagerectangle($im, 0, 0, 15, 15, $black);
/// imageline($im, 0, 0, 15, 15, $black);
/// ```
fn palette() -> Image {
    let im = Image::new_palette(16, 16).expect("image");
    let _white = im.color_allocate(255, 255, 255);
    let black = im.color_allocate(0, 0, 0);
    let green = im.color_allocate(0, 200, 0);
    im.filled_rectangle(3, 3, 12, 12, green);
    im.rectangle(0, 0, 15, 15, black);
    im.line(0, 0, 15, 15, black);
    im
}

fn encode(im: &Image, enc: &Encoder) -> Vec<u8> {
    let mut out = Vec::new();
    im.encode(enc, &mut out).expect("encode");
    out
}

#[test]
fn png_matches_oracle() {
    assert_eq!(encode(&truecolor(), &Encoder::Png(-1)), fixture("tc.png"));
    assert_eq!(encode(&truecolor(), &Encoder::Png(9)), fixture("tc9.png"));
    assert_eq!(encode(&palette(), &Encoder::Png(-1)), fixture("pal.png"));
}

#[test]
fn gif_matches_oracle() {
    let tc = truecolor();
    assert_eq!(encode(&tc, &Encoder::Gif), fixture("tc.gif"));
    // The image stays truecolor (the quantization is on a copy).
    assert!(tc.is_truecolor());
    assert_eq!(encode(&palette(), &Encoder::Gif), fixture("pal.gif"));
}

#[test]
fn jpeg_wbmp_bmp_xbm_webp_match_oracle() {
    assert_eq!(
        encode(&truecolor(), &Encoder::Jpeg(75)),
        fixture("tc75.jpg")
    );
    let pal = palette();
    let fg = php_gd::filters::first_black(&pal);
    assert_eq!(fg, 1);
    assert_eq!(encode(&pal, &Encoder::Wbmp(fg)), fixture("pal.wbmp"));
    assert_eq!(encode(&truecolor(), &Encoder::Bmp(true)), fixture("tc.bmp"));
    assert_eq!(encode(&pal, &Encoder::Bmp(true)), fixture("pal_rle.bmp"));
    assert_eq!(encode(&pal, &Encoder::Bmp(false)), fixture("pal_raw.bmp"));
    let name = format!("{FIXTURES}/fixture.xbm").into_bytes();
    assert_eq!(
        encode(&pal, &Encoder::Xbm(name, fg)),
        fixture("fixture.xbm")
    );
    assert_eq!(
        encode(&truecolor(), &Encoder::Webp(80)),
        fixture("tc80.webp")
    );
    assert_eq!(
        encode(&truecolor(), &Encoder::Webp(101)),
        fixture("tcll.webp")
    );
}

#[test]
fn decoders_read_fixtures() {
    for (name, dec) in [
        ("tc.png", Decoder::Png),
        ("tc.gif", Decoder::Gif),
        ("tc75.jpg", Decoder::Jpeg(true)),
        ("tc.bmp", Decoder::Bmp),
        ("tcll.webp", Decoder::Webp),
    ] {
        let im = Image::decode(dec, &fixture(name)).unwrap_or_else(|| panic!("{name}"));
        assert_eq!((im.width(), im.height()), (32, 24), "{name}");
    }
    let png = Image::decode(Decoder::Png, &fixture("tc.png")).expect("png");
    assert_eq!(png.get_pixel(5, 5), 0x00ff_0000);
    let wbmp = Image::decode(Decoder::Wbmp, &fixture("pal.wbmp")).expect("wbmp");
    assert_eq!((wbmp.width(), wbmp.height()), (16, 16));
    let xbm = Image::decode(Decoder::Xbm, &fixture("fixture.xbm")).expect("xbm");
    assert_eq!((xbm.width(), xbm.height()), (16, 16));
    // Lossless WebP keeps the pixels.
    let ll = Image::decode(Decoder::Webp, &fixture("tcll.webp")).expect("webp");
    assert_eq!(ll.get_pixel(5, 5) & 0x00ff_ffff, 0x00ff_0000);
}

#[test]
fn bad_data_is_rejected_with_messages() {
    let _ = errors::take();
    assert!(Image::decode(Decoder::Png, b"\x89PNG\r\n\x1a\nnot really").is_none());
    let msgs = errors::take();
    assert!(!msgs.is_empty());
    assert!(Image::decode(Decoder::Gif, b"").is_none());
    assert!(Image::decode(Decoder::Xbm, b"").is_none());
    let _ = errors::take();
}

#[test]
fn gd_formats_are_disabled_in_the_system_libgd() {
    let _ = errors::take();
    let out = encode(&palette(), &Encoder::Gd);
    assert!(out.is_empty());
    let msgs = errors::take();
    assert_eq!(msgs.len(), 1);
    assert_eq!(msgs[0].level, errors::Level::Warning);
    assert_eq!(msgs[0].text, b"GD image support has been disabled\n");
}

#[test]
fn palette_operations() {
    let im = palette();
    assert_eq!(im.colors_total(), 3);
    assert_eq!(im.color_components(2), Some([0, 200, 0, 0]));
    assert_eq!(im.color_exact(0, 0, 0), 1);
    assert_eq!(im.color_closest(10, 190, 5), 2);
    assert_eq!(im.pixel_at(5, 5), Some(1));
    assert_eq!(im.pixel_at(5, 4), Some(2));
    assert_eq!(im.pixel_at(16, 0), None);
    im.set_clip(2, 2, 4, 4);
    assert_eq!(im.clip(), [2, 2, 4, 4]);
    assert_eq!(im.pixel_at(5, 5), None);
    assert!(im.palette_to_truecolor());
    assert!(im.is_truecolor());
}

#[test]
fn transforms() {
    let im = truecolor();
    let r = im.rotate(90.0, 0).expect("rotate");
    assert_eq!((r.width(), r.height()), (24, 32));
    let c = im
        .crop(php_gd::Rect {
            x: 2,
            y: 2,
            width: 10,
            height: 5,
        })
        .expect("crop");
    assert_eq!((c.width(), c.height()), (10, 5));
    let s = im.scale(64, 48).expect("scale");
    assert_eq!((s.width(), s.height()), (64, 48));
    let m = php_gd::affine::rotate(90.0).expect("matrix");
    assert!((m[1] - 1.0).abs() < 1e-12);
    let cat = php_gd::affine::concat(&m, &php_gd::affine::translate(1.0, 2.0).expect("t"))
        .expect("concat");
    assert!((cat[4] - 1.0).abs() < 1e-12);
    assert!(im.filter(&php_gd::Filter::Negate));
    assert_eq!(im.get_pixel(5, 5), 0x0000_ffff);
}
